with exploded as (select id, effective_from, explode(discounts) as tier_value from price_tiers) select case when tier_value >= 71 then 'PREMIUM' else 'STANDARD' end as tier_value_tier, avg(tier_value) as avg_tier_value, count(distinct id) as distinct_ids, approx_percentile(tier_value, 0.5) as tier_value_p50, count(distinct id) as distinct_ids_2, percentile_approx(tier_value, array(0.25, 0.5, 0.75)) as tier_value_quartiles, count(*) as row_count from exploded group by tier_value_tier having avg(tier_value) > 0 order by tier_value_tier desc nulls first;
